/* ===================================================================
   1. SHARED HELPERS
   =================================================================== */
const I18N = window.I18N || {};

// Translate a string; {placeholders} are filled from vars.
function t(str, vars) {
  let out = I18N[str] || str;
  if (vars) out = out.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? vars[k] : m));
  return out;
}

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// Option values stay in English so requests arrive in a consistent format.
const SERVICES = {
  formation: 'Company Formation & Market Entry',
  tax: 'Corporate Tax Planning & Optimization',
  audit: 'Statutory & IFRS Financial Audit',
  itpark: 'IT Park Uzbekistan 0% Tax Residency',
  tifc: 'Tashkent International Financial Centre (TIFC) Entry',
  accounting: 'Full Accounting Outsourcing & CFO',
  islamic: 'Islamic Finance & Shariah Corporate Advisory',
  mna: 'M&A / Due Diligence / Valuation'
};

// Opens the consultation modal with an optional pre-selected service and pre-filled notes.
function openConsultModal(service, notes) {
  const modal = document.getElementById('consultModal');
  if (!modal) return;
  const serviceSelect = document.getElementById('serviceInterest');
  const notesField = document.getElementById('clientNotes');
  if (service && serviceSelect) serviceSelect.value = service;
  if (typeof notes === 'string' && notesField) notesField.value = notes;
  showConsultForm();
  if (!modal.open) modal.showModal();
  trackEvent('open_consultation', { service: service || 'general' });
}

function showConsultForm() {
  const form = document.getElementById('consultForm');
  const success = document.getElementById('consultSuccess');
  if (form) form.hidden = false;
  if (success) success.hidden = true;
}

/* ===================================================================
   2. COOKIE CONSENT, ANALYTICS & LEAD TRACKING
   Analytics scripts load only after the visitor clicks "Accept".
   With no IDs configured above, nothing loads and no banner shows.
   =================================================================== */
const CONSENT_KEY = 'mezon-consent';
const analyticsEnabled = () => Boolean(ANALYTICS.ga4 || ANALYTICS.yandexMetrica || ANALYTICS.metaPixel);
let analyticsLoaded = false;

function readConsent() {
  try { return localStorage.getItem(CONSENT_KEY); } catch (e) { return null; }
}

function saveConsent(value) {
  try { localStorage.setItem(CONSENT_KEY, value); } catch (e) { /* storage unavailable */ }
}

function loadScript(src) {
  const s = document.createElement('script');
  s.async = true;
  s.src = src;
  document.head.appendChild(s);
}

function loadAnalytics() {
  if (analyticsLoaded) return;
  analyticsLoaded = true;

  if (ANALYTICS.ga4) {
    loadScript(`https://www.googletagmanager.com/gtag/js?id=${encodeURIComponent(ANALYTICS.ga4)}`);
    window.dataLayer = window.dataLayer || [];
    window.gtag = function () { window.dataLayer.push(arguments); };
    window.gtag('js', new Date());
    window.gtag('config', ANALYTICS.ga4);
  }

  if (ANALYTICS.yandexMetrica) {
    window.ym = window.ym || function () { (window.ym.a = window.ym.a || []).push(arguments); };
    window.ym.l = Date.now();
    loadScript('https://mc.yandex.ru/metrika/tag.js');
    window.ym(Number(ANALYTICS.yandexMetrica), 'init', { clickmap: true, trackLinks: true, accurateTrackBounce: true, webvisor: false });
  }

  if (ANALYTICS.metaPixel) {
    const fbq = window.fbq = function () {
      fbq.callMethod ? fbq.callMethod.apply(fbq, arguments) : fbq.queue.push(arguments);
    };
    if (!window._fbq) window._fbq = fbq;
    fbq.push = fbq;
    fbq.loaded = true;
    fbq.version = '2.0';
    fbq.queue = [];
    loadScript('https://connect.facebook.net/en_US/fbevents.js');
    fbq('init', ANALYTICS.metaPixel);
    fbq('track', 'PageView');
  }
}

// Sends one event to whichever analytics tools are loaded.
function trackEvent(name, params) {
  if (!analyticsLoaded) return;
  if (window.gtag) window.gtag('event', name, params || {});
  if (window.ym && ANALYTICS.yandexMetrica) window.ym(Number(ANALYTICS.yandexMetrica), 'reachGoal', name, params || {});
  if (window.fbq && name.startsWith('lead_')) window.fbq('track', 'Contact', params || {});
}

function initConsentAndAnalytics() {
  const banner = document.getElementById('cookieBanner');
  const settingsBtn = document.getElementById('cookieSettingsBtn');
  if (!analyticsEnabled()) {
    if (settingsBtn) settingsBtn.hidden = true;
    return;
  }

  const consent = readConsent();
  if (consent === 'granted') loadAnalytics();
  else if (consent !== 'denied' && banner) banner.hidden = false;

  const accept = document.getElementById('cookieAccept');
  const decline = document.getElementById('cookieDecline');
  if (accept) accept.addEventListener('click', () => {
    saveConsent('granted');
    banner.hidden = true;
    loadAnalytics();
  });
  if (decline) decline.addEventListener('click', () => {
    saveConsent('denied');
    banner.hidden = true;
  });
  if (settingsBtn) settingsBtn.addEventListener('click', () => { banner.hidden = false; });
}

// Every WhatsApp / Telegram / Instagram click counts as a lead.
function initLeadTracking() {
  document.addEventListener('click', e => {
    const link = e.target.closest('a[href]');
    if (!link) return;
    const href = link.getAttribute('href');
    let channel = null;
    if (href.includes('wa.me')) channel = 'whatsapp';
    else if (href.includes('t.me')) channel = 'telegram';
    else if (href.includes('instagram.com')) channel = 'instagram';
    if (channel) trackEvent('lead_' + channel, { page_language: document.documentElement.lang });
  });
}

/* ===================================================================
   3. UZBEKISTAN TAX & PAYROLL CALCULATOR
   =================================================================== */
let recalculateTaxes = () => {};

function initTaxCalculator() {
  const revInput = document.getElementById('annualRevenue');
  const marginInput = document.getElementById('profitMargin');
  const countInput = document.getElementById('employeeCount');
  const salaryInput = document.getElementById('avgSalary');
  const regimeSelect = document.getElementById('regimeSelect');
  const foreignInput = document.getElementById('foreignStaffShare');
  const foreignGroup = document.getElementById('foreignStaffGroup');
  const currencySelect = document.getElementById('currencySelect');
  if (!revInput || !regimeSelect) return;

  const el = id => document.getElementById(id);
  const regimeBadge = el('regimeBadge');
  const regimeBox = el('itParkBox');

  // Indicative assumptions shared by both regimes
  const CIT_RATE = 0.15;
  const VAT_RATE = 0.12;
  const VALUE_ADDED_SHARE = 0.35;
  const PIT_RATE = 0.12;
  const SOCIAL_TAX_RATE = 0.12;

  const REGIMES = {
    itpark: {
      tag: '<i class="fa-solid fa-crown"></i> ' + t('IT Park Resident Regime'),
      badge: t('IT Park Comparison'),
      cit: t('Corporate Income Tax (0%):'),
      vat: t('VAT on Export Services (0%):'),
      pit: t('Employee PIT (Reduced to 7.5%):'),
      fee: t('IT Park Fee (1% of Revenue):')
    },
    tifc: {
      tag: '<i class="fa-solid fa-landmark"></i> ' + t('TIFC Participant Regime'),
      badge: t('TIFC Comparison'),
      cit: t('CIT on Qualifying Financial Services (0%):'),
      vat: t('VAT on Qualifying Financial Services (Exempt):'),
      pit: t('Employee PIT (0% Foreign / 7% Resident):'),
      fee: null
    }
  };

  function formatMoney(amountUSD, currency) {
    if (currency === 'UZS') {
      return Math.round(amountUSD * USD_TO_UZS).toLocaleString('en-US') + ' UZS';
    }
    return '$' + Math.round(amountUSD).toLocaleString('en-US');
  }

  function recalculate() {
    const revenueUSD = parseFloat(revInput.value) || 0;
    const marginPct = parseFloat(marginInput.value) || 0;
    const employees = Math.max(0, parseInt(countInput.value, 10) || 0);
    const monthlySalaryUSD = Math.max(0, parseFloat(salaryInput.value) || 0);
    const foreignShare = (parseFloat(foreignInput.value) || 0) / 100;
    const curr = currencySelect.value;
    const regime = regimeSelect.value;

    el('revValBadge').textContent = formatMoney(revenueUSD, curr);
    el('marginValBadge').textContent = marginPct + '%';
    el('foreignValBadge').textContent = Math.round(foreignShare * 100) + '%';

    const operatingProfit = revenueUSD * (marginPct / 100);
    const annualPayroll = employees * monthlySalaryUSD * 12;

    // Standard regime
    const cit = operatingProfit * CIT_RATE;
    const vat = revenueUSD * VALUE_ADDED_SHARE * VAT_RATE;
    const payrollTaxes = annualPayroll * (PIT_RATE + SOCIAL_TAX_RATE);
    const totalStandard = cit + vat + payrollTaxes;
    const netStandard = operatingProfit - cit;

    el('standardCitRes').textContent = formatMoney(cit, curr);
    el('standardVatRes').textContent = formatMoney(vat, curr);
    el('standardPayrollRes').textContent = formatMoney(payrollTaxes, curr);
    el('standardTotalRes').textContent = formatMoney(totalStandard, curr);
    el('standardNetProfit').textContent = formatMoney(netStandard, curr);

    if (foreignGroup) foreignGroup.hidden = regime !== 'tifc';

    if (regime === 'none') {
      regimeBox.hidden = true;
      regimeBadge.textContent = t('Standard General Regime');
      return;
    }
    regimeBox.hidden = false;

    const cfg = REGIMES[regime];
    el('regimeTag').innerHTML = cfg.tag;
    el('regimeCitLabel').textContent = cfg.cit;
    el('regimeVatLabel').textContent = cfg.vat;
    el('regimePitLabel').textContent = cfg.pit;
    regimeBadge.textContent = cfg.badge;

    let pit = 0;
    let fee = 0;
    if (regime === 'itpark') {
      pit = annualPayroll * 0.075;
      fee = revenueUSD * 0.01;
    } else {
      pit = annualPayroll * (1 - foreignShare) * 0.07;
    }

    const feeRow = el('regimeFeeRow');
    feeRow.hidden = !cfg.fee;
    if (cfg.fee) {
      el('regimeFeeLabel').textContent = cfg.fee;
      el('regimeFeeRes').textContent = formatMoney(fee, curr);
    }

    const totalRegime = pit + fee;
    el('itParkPitRes').textContent = formatMoney(pit, curr);
    el('itParkTotalRes').textContent = formatMoney(totalRegime, curr);
    el('regimeNetProfit').textContent = formatMoney(operatingProfit - fee, curr);
    el('savingsAmount').textContent = formatMoney(Math.max(0, totalStandard - totalRegime), curr) + ' ' + t('/ year');
  }

  recalculateTaxes = recalculate;

  [revInput, marginInput, countInput, salaryInput, regimeSelect, foreignInput, currencySelect].forEach(input => {
    if (!input) return;
    input.addEventListener('input', recalculate);
    input.addEventListener('change', recalculate);
  });

  recalculate();

  const printBtn = el('printTaxReportBtn');
  if (printBtn) {
    printBtn.addEventListener('click', () => {
      document.body.classList.add('print-tax-report');
      trackEvent('print_tax_report');
      window.print();
    });
    window.addEventListener('afterprint', () => document.body.classList.remove('print-tax-report'));
  }

  // Discuss results with advisor
  [el('consultTaxResultsBtn'), el('execCalcBtn')].forEach(b => {
    if (!b) return;
    b.addEventListener('click', () => {
      const regimeName = regimeSelect.options[regimeSelect.selectedIndex].text;
      const service = regimeSelect.value === 'tifc' ? SERVICES.tifc : SERVICES.tax;
      openConsultModal(service, t(
        'Estimated annual revenue: {rev}, profit margin: {margin}%, employees: {emp}, comparison regime: {regime}. Requesting custom tax structuring advice.',
        {
          rev: '$' + parseInt(revInput.value, 10).toLocaleString('en-US'),
          margin: marginInput.value,
          emp: countInput.value,
          regime: regimeName
        }));
    });
  });

  initToolTabs();
}

function initToolTabs() {
  const toolTabs = Array.from(document.querySelectorAll('.tool-tab'));
  const toolPanels = document.querySelectorAll('.tool-panel');

  function activate(tab) {
    toolTabs.forEach(tb => {
      tb.classList.remove('active');
      tb.setAttribute('aria-selected', 'false');
      tb.setAttribute('tabindex', '-1');
    });
    toolPanels.forEach(p => p.classList.remove('active'));

    tab.classList.add('active');
    tab.setAttribute('aria-selected', 'true');
    tab.removeAttribute('tabindex');
    const targetPanel = document.getElementById(tab.getAttribute('aria-controls'));
    if (targetPanel) targetPanel.classList.add('active');
  }

  // In RTL the visual order is reversed, so swap the arrow keys.
  const isRtl = () => document.documentElement.dir === 'rtl';

  toolTabs.forEach((tab, i) => {
    tab.addEventListener('click', () => activate(tab));
    tab.addEventListener('keydown', e => {
      let step = 0;
      if (e.key === 'ArrowRight') step = isRtl() ? -1 : 1;
      if (e.key === 'ArrowLeft') step = isRtl() ? 1 : -1;
      if (!step) return;
      e.preventDefault();
      const next = toolTabs[(i + step + toolTabs.length) % toolTabs.length];
      activate(next);
      next.focus();
    });
  });

  window.activateToolTab = id => {
    const tab = document.getElementById(id);
    if (tab) activate(tab);
  };
}

