/* ===================================================================
   5. AUDIT READINESS DIAGNOSTIC (TAB 3)
   =================================================================== */
function initAuditDiagnostic() {
  const calcScoreBtn = document.getElementById('calculateAuditScoreBtn');
  const resultsCard = document.getElementById('auditScoreResult');
  if (!calcScoreBtn || !resultsCard) return;

  let lastScore = 0;
  let lastBadge = '';

  resultsCard.addEventListener('click', e => {
    if (!e.target.closest('[data-action="request-audit"]')) return;
    openConsultModal(SERVICES.audit,
      t('Audit readiness diagnostic score: {score}/100 ({badge}). Requesting pre-audit review and statutory audit proposal.', { score: lastScore, badge: lastBadge }));
  });

  calcScoreBtn.addEventListener('click', () => {
    const formData = new FormData(document.getElementById('auditDiagnosticForm'));
    const q1 = formData.get('q1');
    const q2 = formData.get('q2');
    const q3 = formData.get('q3');
    const q4 = formData.get('q4');
    const q5 = formData.get('q5');

    let score = 0;
    const recommendations = [];

    if (q1 === 'ifrs') {
      score += 25;
    } else if (q1 === 'nas') {
      score += 15;
      recommendations.push(t("Your statutory reporting follows Uzbek NAS; if seeking foreign investment or bank credit, transition to IFRS is required."));
    } else {
      score += 5;
      recommendations.push(t("Hybrid or non-formalized accounts create severe risk of tax restatements and penalties."));
    }

    if (q2 === 'no') {
      score += 20;
    } else if (q2 === 'yes_low') {
      score += 12;
      recommendations.push(t("Ensure customs declarations and foreign trade contracts are properly registered for currency control purposes."));
    } else {
      score += 5;
      recommendations.push(t("Significant cross-border and related-party transactions require transfer pricing documentation under the Uzbekistan Tax Code."));
    }

    if (q3 === 'within_year') {
      score += 20;
    } else if (q3 === 'over_year') {
      score += 10;
      recommendations.push(t("More than 12 months without independent review leaves vulnerabilities in VAT and payroll calculations."));
    } else {
      score += 5;
      recommendations.push(t("Conduct a pre-audit diagnostic before the Tax Committee's automated risk scoring flags your company."));
    }

    if (q4 === 'expert') {
      score += 20;
    } else if (q4 === 'internal') {
      score += 12;
      recommendations.push(t("Single in-house accountants often lack specialized cross-border tax treaty experience; external oversight is advised."));
    } else {
      score += 2;
      recommendations.push(t("Freelance bookkeeping without formal liability contracts represents a major compliance liability in Uzbekistan."));
    }

    if (q5 === 'yes') {
      score += 15;
    } else if (q5 === 'informal') {
      score += 8;
      recommendations.push(t("Formalize annual inventory commission acts to satisfy statutory auditor verification."));
    } else {
      recommendations.push(t("Unreconciled assets will result in a qualified or adverse audit opinion."));
    }

    if (recommendations.length === 0) {
      recommendations.push(t("Your controls are in strong shape. Maintain annual independent audits and monitor 2026 Tax Code amendments."));
    }

    let statusText, statusColor, statusBadge;
    if (score >= 80) {
      statusText = t("Excellent Audit Readiness (Low Risk)");
      statusColor = "var(--accent-emerald)";
      statusBadge = t("AUDIT READY");
    } else if (score >= 50) {
      statusText = t("Moderate Compliance Risk (Action Recommended)");
      statusColor = "var(--accent-gold)";
      statusBadge = t("PRE-AUDIT REMEDIATION NEEDED");
    } else {
      statusText = t("High Regulatory Exposure (Urgent Review Required)");
      statusColor = "var(--danger)";
      statusBadge = t("URGENT COMPLIANCE RISK");
    }
    lastScore = score;
    lastBadge = statusBadge;
    trackEvent('audit_diagnostic_completed', { score });

    resultsCard.classList.remove('hidden');
    resultsCard.innerHTML = `
      <div class="audit-result-head">
        <div>
          <span class="audit-result-badge" style="color: ${statusColor};">${statusBadge}</span>
          <h3>${t('Compliance Score: {score} / 100', { score })}</h3>
          <div class="audit-score-bar"><span style="width: ${score}%; background: ${statusColor};"></span></div>
          <p style="color: ${statusColor};">${statusText}</p>
        </div>
        <button class="btn btn-primary" type="button" data-action="request-audit">
          <i class="fa-solid fa-shield-halved"></i> ${t('Request Pre-Audit Remediation')}
        </button>
      </div>

      <div class="audit-findings">
        <strong><i class="fa-solid fa-triangle-exclamation"></i> ${t('Key Remediation Findings for Your Entity:')}</strong>
        <ul>
          ${recommendations.map(r => `<li><i class="fa-solid fa-arrow-right"></i><span>${r}</span></li>`).join('')}
        </ul>
      </div>

      <p class="audit-disclaimer">
        ${t('* This diagnostic provides preliminary guidance based on the Uzbekistan Tax Code (2026) and Chamber of Auditors guidelines. It is not an audit opinion.')}
      </p>
    `;

    resultsCard.scrollIntoView({ behavior: 'smooth', block: 'center' });
  });
}

