/* ===================================================================
   7. LIVE CENTRAL BANK OF UZBEKISTAN EXCHANGE RATES
   =================================================================== */
function initCbuRates() {
  const items = document.querySelectorAll('.rate-item[data-ccy]');
  const dateEl = document.getElementById('cbuDate');
  const usdOption = document.getElementById('usdOptionLabel');
  if (!items.length) return;

  const fallback = { USD: { Rate: '11808.76', Diff: '-12.42' } };

  function render(rates, dateLabel) {
    items.forEach(item => {
      const ccy = item.getAttribute('data-ccy');
      const r = rates[ccy];
      if (!r) return;
      const rate = parseFloat(r.Rate);
      const diff = parseFloat(r.Diff) || 0;
      const prev = rate - diff;
      const pct = prev ? (diff / prev) * 100 : 0;
      item.querySelector('.rate-val').textContent =
        rate.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
      const trend = item.querySelector('.trend');
      const dir = diff > 0 ? 'up' : diff < 0 ? 'down' : 'neutral';
      trend.className = 'trend ' + dir;
      const icon = dir === 'up' ? 'fa-arrow-trend-up' : dir === 'down' ? 'fa-arrow-trend-down' : 'fa-minus';
      trend.innerHTML = `<i class="fa-solid ${icon}"></i> ${diff > 0 ? '+' : ''}${pct.toFixed(2)}%`;
    });

    if (rates.USD) {
      USD_TO_UZS = parseFloat(rates.USD.Rate) || USD_TO_UZS;
      if (usdOption) {
        usdOption.textContent = `USD ($) [1 USD ≈ ${Math.round(USD_TO_UZS).toLocaleString('en-US')} UZS]`;
      }
      recalculateTaxes();
    }
    if (dateEl) dateEl.textContent = dateLabel;
  }

  render(fallback, t('Reference rate: {date}', { date: '01.10.2026' }));

  const controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
  const timer = controller ? setTimeout(() => controller.abort(), 8000) : null;

  fetch('https://cbu.uz/en/arkhiv-kursov-valyut/json/', controller ? { signal: controller.signal } : {})
    .then(res => {
      if (!res.ok) throw new Error('HTTP ' + res.status);
      return res.json();
    })
    .then(list => {
      const rates = {};
      list.forEach(r => { rates[r.Ccy] = r; });
      const date = rates.USD ? rates.USD.Date : '';
      render(rates, t('Official rate: {date}', { date }));
    })
    .catch(() => {
      if (dateEl) dateEl.textContent = t('Reference rate: {date}', { date: '01.10.2026' }) + ' ' + t('(live feed unavailable)');
    })
    .finally(() => { if (timer) clearTimeout(timer); });
}

/* ===================================================================
   8. LIVE ADVISORY CHATBOT WIDGET
   =================================================================== */
function initLiveChat() {
  const toggleBtn = document.getElementById('chatToggleBtn');
  const chatWindow = document.getElementById('chatWindow');
  const closeBtn = document.getElementById('chatCloseBtn');
  const chatMessages = document.getElementById('chatMessages');
  const chatInputForm = document.getElementById('chatInputForm');
  const chatInputField = document.getElementById('chatInputField');
  const quickChips = document.querySelectorAll('.quick-chip');
  if (!toggleBtn || !chatWindow) return;

  const tgLink = CONTACT.telegram ? `<a href="https://t.me/${CONTACT.telegram}" target="_blank" rel="noopener" class="chat-link tg">@${CONTACT.telegram}</a>` : '';
  const waLink = CONTACT.whatsapp ? `<a href="https://wa.me/${CONTACT.whatsapp}" target="_blank" rel="noopener" class="chat-link wa">${t('Message us')}</a>` : '';
  const igLink = CONTACT.instagram ? `<a href="https://instagram.com/${CONTACT.instagram}" target="_blank" rel="noopener" class="chat-link ig">@${CONTACT.instagram}</a>` : '';
  const contactLines = [
    tgLink && `• <strong>Telegram:</strong> ${tgLink}`,
    waLink && `• <strong>WhatsApp:</strong> ${waLink}`,
    igLink && `• <strong>Instagram:</strong> ${igLink}`
  ].filter(Boolean).join('<br>');

  function openChat() {
    chatWindow.classList.remove('hidden');
    toggleBtn.querySelector('.chat-icon-open').classList.add('hidden');
    toggleBtn.querySelector('.chat-icon-close').classList.remove('hidden');
    toggleBtn.setAttribute('aria-expanded', 'true');
    chatInputField.focus();
    trackEvent('open_chat');
  }

  function closeChat() {
    chatWindow.classList.add('hidden');
    toggleBtn.querySelector('.chat-icon-open').classList.remove('hidden');
    toggleBtn.querySelector('.chat-icon-close').classList.add('hidden');
    toggleBtn.setAttribute('aria-expanded', 'false');
  }

  toggleBtn.addEventListener('click', () => {
    if (chatWindow.classList.contains('hidden')) openChat();
    else closeChat();
  });
  if (closeBtn) closeBtn.addEventListener('click', closeChat);
  ['openChatQuickBtn', 'openChatHeroChip'].forEach(id => {
    const b = document.getElementById(id);
    if (b) b.addEventListener('click', openChat);
  });
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && !chatWindow.classList.contains('hidden')) closeChat();
  });

  // isHtml: trusted bot markup; user text is always escaped.
  function appendMessage(content, isIncoming, isHtml) {
    const msgDiv = document.createElement('div');
    msgDiv.className = `message ${isIncoming ? 'incoming' : 'outgoing'}`;
    const timeStr = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    msgDiv.innerHTML = `
      <div class="msg-bubble"><p>${isHtml ? content : escapeHtml(content)}</p></div>
      <span class="msg-time">${timeStr}</span>
    `;
    chatMessages.appendChild(msgDiv);
    chatMessages.scrollTop = chatMessages.scrollHeight;
  }

  function showTyping() {
    const typing = document.createElement('div');
    typing.className = 'message incoming typing';
    typing.innerHTML = '<div class="msg-bubble"><span class="typing-dots"><span></span><span></span><span></span></span></div>';
    chatMessages.appendChild(typing);
    chatMessages.scrollTop = chatMessages.scrollHeight;
    return typing;
  }

  const has = (q, words) => words.some(w => q.includes(w));

  function botReply(userQuery) {
    const q = userQuery.toLowerCase();

    // Order matters: specific topics first, generic "tax" last.
    if (has(q, ['tifc', 'txmm', 'тмфц', 'financial centre', 'financial center', 'english law', 'common law', 'tax holiday', 'tax vacation', 'финансовый центр', 'английское право', 'moliya markazi', 'ingliz huquqi', 'المركز المالي', 'مركز طشقند', 'القانون الإنجليزي'])) {
      return '🏛️ ' + t('<strong>Tashkent International Financial Centre (TIFC)</strong>:<br>• English &amp; Welsh common law plus an independent commercial court with English-language proceedings<br>• Tax incentives until <strong>1 January 2076</strong><br>• 0% CIT &amp; social tax on Islamic banking, fund management, insurance brokerage &amp; securities services<br>• 0% PIT for foreign staff, 7% for residents<br>• Capital gains on securities exempt; 5-year visas, no work permits') +
        `<br><a href="#tifc" class="chat-link">${t('See full TIFC incentives →')}</a>`;
    }
    if (has(q, ['it park', 'itpark', 'айти', 'ит парк', 'software', 'tech', 'dasturiy'])) {
      return '💻 ' + t('<strong>IT Park Uzbekistan</strong> grants 0% Corporate Tax, 0% VAT on export services, 0% customs duties on equipment, and a reduced 7.5% employee income tax until 2040. Residents pay 1% of revenue to the IT Park Directorate. We can prepare your business plan and residency application.');
    }
    if (has(q, ['islamic', 'shariah', 'sharia', 'arab', 'gcc', 'sukuk', 'murabaha', 'ислам', 'шариат', 'islom', 'إسلامي', 'الخليج', 'شريعة', 'الشريعة'])) {
      return '🌙 ' + t('<strong>Mezon Advisory</strong> specializes in Islamic finance advisory for Gulf/Arab investors (UAE, Saudi Arabia, Qatar). We assist with Double Tax Treaty relief, Murabaha structuring, Shariah-compliant joint ventures, and TIFC licensing, where Islamic banking services enjoy 0% corporate tax until 2076.');
    }
    if (has(q, ['register', 'registration', 'formation', 'open company', 'set up', 'setup', 'llc', 'регистрац', 'открыть компан', 'ооо', 'kompaniya', 'ochish', 'تأسيس', 'شركة'])) {
      return '🏢 ' + t('To register a company in Uzbekistan, we usually recommend a <strong>Foreign Enterprise LLC</strong>. Setup takes 5–7 business days and can be handled 100% remotely via Power of Attorney. Would you like us to review your required documents?');
    }
    if (has(q, ['audit', 'ifrs', 'nas', 'мсфо', 'аудит', 'mhxs', 'تدقيق'])) {
      return '📑 ' + t('We provide statutory audits, NAS-to-IFRS conversion and internal control diagnostics. Try the free Audit Readiness Diagnostic in our tools section, or request an audit proposal.');
    }
    if (has(q, ['speak', 'advisor', 'call', 'contact', 'telegram', 'whatsapp', 'phone', 'связ', 'консульт', 'позвон', 'контакт', "bog'lan", 'maslahatchi', 'aloqa', 'تواصل', 'اتصال', 'مستشار'])) {
      return '👤 ' + t('Connect directly with our advisory team:') + '<br>' + contactLines;
    }
    if (has(q, ['tax', 'vat', 'rate', 'cit', 'налог', 'ндс', 'soliq', 'qqs', 'ضرائب', 'ضريبة'])) {
      return '📊 ' + t('Standard Uzbekistan tax rates (2026):<br>• Corporate Income Tax: <strong>15%</strong><br>• VAT: <strong>12%</strong><br>• Employee PIT: <strong>12%</strong><br>• Employer Social Tax: <strong>12%</strong><br>Special regimes: <strong>IT Park</strong> (0% CIT, 7.5% PIT) and <strong>TIFC</strong> (0% CIT on qualifying financial services until 2076).');
    }
    return t('Thank you for reaching out! Our advisory team will review your message: "{msg}". For an instant reply, message us directly:',
      { msg: `<em>${escapeHtml(userQuery)}</em>` }) + '<br>' + contactLines;
  }

  function handleQuery(text) {
    appendMessage(text, false, false);
    const typing = showTyping();
    setTimeout(() => {
      typing.remove();
      appendMessage(botReply(text), true, true);
    }, 650);
  }

  chatMessages.addEventListener('click', e => {
    if (e.target.closest('a[href^="#"]')) closeChat();
  });

  if (chatInputForm) {
    chatInputForm.addEventListener('submit', e => {
      e.preventDefault();
      const text = chatInputField.value.trim();
      if (!text) return;
      chatInputField.value = '';
      handleQuery(text);
    });
  }

  quickChips.forEach(chip => {
    chip.addEventListener('click', () => handleQuery(chip.textContent.replace(/^\S+\s/, '')));
  });
}

/* ===================================================================
   9. CONSULTATION & STRATEGY BOOKING MODAL
   =================================================================== */
function initConsultationModal() {
  const modal = document.getElementById('consultModal');
  const consultForm = document.getElementById('consultForm');
  if (!modal || !consultForm) return;

  ['openConsultModalBtn', 'heroBookBtn', 'finalBookBtn'].forEach(id => {
    const btn = document.getElementById(id);
    if (btn) btn.addEventListener('click', () => openConsultModal());
  });

  const formationBtn = document.getElementById('startFormationModalBtn');
  if (formationBtn) formationBtn.addEventListener('click', () => openConsultModal(SERVICES.formation));

  document.querySelectorAll('.card-action-btn').forEach(btn => {
    btn.addEventListener('click', () => openConsultModal(SERVICES[btn.getAttribute('data-service')]));
  });

  const closeModalBtn = document.getElementById('closeConsultModalBtn');
  if (closeModalBtn) closeModalBtn.addEventListener('click', () => modal.close());

  // Close only when the backdrop itself is clicked
  modal.addEventListener('click', e => {
    if (e.target === modal) modal.close();
  });

  const success = document.getElementById('consultSuccess');
  const waBtn = document.getElementById('sendViaWhatsApp');
  const tgBtn = document.getElementById('sendViaTelegram');
  const backBtn = document.getElementById('consultBackBtn');
  let lastMessage = '';

  consultForm.addEventListener('submit', e => {
    e.preventDefault();
    const val = id => document.getElementById(id).value.trim();
    const name = val('clientName');
    const serviceSelect = document.getElementById('serviceInterest');
    const serviceLabel = serviceSelect.options[serviceSelect.selectedIndex].text;

    lastMessage =
      t('Hello Mezon Advisory! I am requesting a consultation via your website:') + '\n\n' +
      `• ${t('Name')}: ${name}\n` +
      `• ${t('Company')}: ${val('clientCompany')}\n` +
      `• ${t('Email')}: ${val('clientEmail')}\n` +
      `• ${t('Contact')}: ${val('clientTelegram') || 'N/A'}\n` +
      `• ${t('Service')}: ${serviceLabel}\n` +
      `• ${t('Notes')}: ${val('clientNotes') || t('Ready to discuss.')}\n` +
      `• ${t('Website language')}: ${document.documentElement.lang.toUpperCase()}`;

    if (waBtn && CONTACT.whatsapp) waBtn.href = `https://wa.me/${CONTACT.whatsapp}?text=${encodeURIComponent(lastMessage)}`;

    consultForm.hidden = true;
    if (success) success.hidden = false;
    trackEvent('consultation_form_completed', { service: val('serviceInterest') });
    showToast(t('Thank you, {name}! Choose WhatsApp or Telegram to send your request.', { name }));
  });

  if (tgBtn) {
    tgBtn.addEventListener('click', () => {
      if (navigator.clipboard && lastMessage) {
        navigator.clipboard.writeText(lastMessage)
          .then(() => showToast(t('Request copied. Paste it into the Telegram chat.')))
          .catch(() => {});
      }
    });
  }

  [waBtn, tgBtn].forEach(b => {
    if (!b) return;
    b.addEventListener('click', () => {
      setTimeout(() => {
        consultForm.reset();
        modal.close();
      }, 300);
    });
  });

  if (backBtn) backBtn.addEventListener('click', showConsultForm);
  modal.addEventListener('close', showConsultForm);
}

