function initFaqAccordion() {
  const accordionItems = document.querySelectorAll('.accordion-item');

  accordionItems.forEach(item => {
    const header = item.querySelector('.accordion-header');
    if (!header) return;
    header.addEventListener('click', () => {
      const isOpen = item.classList.contains('active');
      accordionItems.forEach(i => {
        i.classList.remove('active');
        const h = i.querySelector('.accordion-header');
        if (h) h.setAttribute('aria-expanded', 'false');
      });
      if (!isOpen) {
        item.classList.add('active');
        header.setAttribute('aria-expanded', 'true');
      }
    });
  });
}

/* ===================================================================
   12. MOBILE NAVIGATION & TOAST
   =================================================================== */
function initMobileNavigation() {
  const mobileToggle = document.getElementById('mobileMenuToggle');
  const navMenu = document.getElementById('navMenu');

  function setMenu(open) {
    navMenu.classList.toggle('open', open);
    mobileToggle.setAttribute('aria-expanded', String(open));
    const icon = mobileToggle.querySelector('i');
    if (icon) icon.className = open ? 'fa-solid fa-xmark' : 'fa-solid fa-bars';
  }

  if (mobileToggle && navMenu) {
    mobileToggle.addEventListener('click', e => {
      e.stopPropagation();
      setMenu(!navMenu.classList.contains('open'));
    });
    navMenu.querySelectorAll('.nav-item').forEach(link => link.addEventListener('click', () => setMenu(false)));
    document.addEventListener('click', e => {
      if (navMenu.classList.contains('open') && !navMenu.contains(e.target)) setMenu(false);
    });
  }

  const header = document.getElementById('navbar');
  if (header) {
    const onScroll = () => header.classList.toggle('scrolled', window.scrollY > 40);
    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();
  }
}

function showToast(message) {
  const container = document.getElementById('toastContainer');
  if (!container) return;

  const toast = document.createElement('div');
  toast.className = 'toast';
  toast.innerHTML = `<i class="fa-solid fa-circle-check" style="color:var(--accent-emerald-light);"></i> <span>${escapeHtml(message)}</span>`;
  container.appendChild(toast);

  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transition = 'opacity 0.3s ease-out';
    setTimeout(() => toast.remove(), 300);
  }, 4500);
}
